BEGIN;SET LOCAL lock_timeout='5s';
DO $guard$ BEGIN
IF md5(pg_get_functiondef('private.pc_item_location(text)'::regprocedure))<>'7237bb7dfbeb6b1a020cce948abe7126' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pc_item_location(text)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('private.pc_store_items(uuid,text,integer,text)'::regprocedure))<>'dca8920cda2e1236352dcee8c4494694' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pc_store_items(uuid,text,integer,text)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('private.pc_deliver_items(uuid,jsonb,text)'::regprocedure))<>'88e6b4ede79698ee36a0b568f1387f90' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pc_deliver_items(uuid,jsonb,text)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('play_pc_items()'::regprocedure))<>'4666cfa23eb92a848e66cfc003ff594c' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_pc_items()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('play_pc_item_transfer(uuid,text,text,integer)'::regprocedure))<>'b62922f112954cb39bb232405c937208' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_pc_item_transfer(uuid,text,text,integer)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('private.materialize_pass_crates(uuid)'::regprocedure))<>'dc2036e60ff03257d1ea481540157b89' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.materialize_pass_crates(uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('private.pass_schedule_calendar(uuid)'::regprocedure))<>'400ce1c63c7a9f5ee378da5b61a369ba' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pass_schedule_calendar(uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('private.oak_calendar_projection(uuid)'::regprocedure))<>'ed14aef531f11de63d5694352e6b153c' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.oak_calendar_projection(uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('play_claim_daily_supply()'::regprocedure))<>'1866110951fef370b3200c4f22b942e8' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_claim_daily_supply()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
IF md5(pg_get_functiondef('play_oak_checkin_state()'::regprocedure))<>'c461a90e0d06ccfd098ffe74d46cbee7' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_oak_checkin_state()'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'REWARD_BOX_SOURCE_OR_PERMISSION_DRIFT';END IF;
END $guard$;
DO $plan$ BEGIN IF (SELECT plan FROM private.supply_rotation_config WHERE id) IS DISTINCT FROM '{"oak":{"coins":150,"stones":["firestone","waterstone","thunderstone","leafstone","moonstone"],"exclude":["masterball"],"rareBalls":["moonball","cherishball","gsball","ashball","cloneball","darkball"],"eligibility":"seven-consecutive-daily-check-ins","candyQuantity":10},"weeks":[{"daily":["figy","moonball","firestone","silverpinap","ultraball","wiki","gsball"],"weekly":{"lum":2,"bait":1,"lure":1,"moonball":1,"greatball":2}},{"daily":["mago","hisuiultraball","waterstone","razz","cherishball","aguav","jetball"],"weekly":{"bait":1,"lure":1,"sitrus":2,"cherishball":1,"hisuigreatball":2}},{"daily":["iapapa","gigatonball","thunderstone","silverpinap","ashball","figy","moonball"],"weekly":{"bait":1,"lure":1,"gsball":1,"persim":2,"wingball":2}},{"daily":["wiki","ultraball","leafstone","mago","cloneball","aguav","goldenrazz"],"weekly":{"lum":2,"bait":1,"lure":1,"ashball":1,"leadenball":2}}],"status":"local-proposal-not-active","version":1,"dailyCoins":50,"weeklyCoins":150}'::jsonb THEN RAISE EXCEPTION 'REWARD_PLAN_DRIFT';END IF;END $plan$;
DO $absent$ BEGIN IF to_regclass('private.reward_gift_boxes') IS NOT NULL THEN RAISE EXCEPTION 'REWARD_BOXES_ALREADY_INSTALLED';END IF;IF to_regprocedure('play_reward_box_open(uuid,uuid,text)') IS NOT NULL THEN RAISE EXCEPTION 'REWARD_HELPER_NAME_EXISTS';END IF;IF to_regprocedure('private.calendar_reward_details(jsonb)') IS NOT NULL THEN RAISE EXCEPTION 'REWARD_HELPER_NAME_EXISTS';END IF;IF to_regprocedure('private.oak_berry_preview(uuid,date)') IS NOT NULL THEN RAISE EXCEPTION 'REWARD_HELPER_NAME_EXISTS';END IF;IF to_regprocedure('private.queue_reward_gift_box(uuid,jsonb,text)') IS NOT NULL THEN RAISE EXCEPTION 'REWARD_HELPER_NAME_EXISTS';END IF;IF to_regprocedure('private.reward_gift_boxes_json(uuid)') IS NOT NULL THEN RAISE EXCEPTION 'REWARD_HELPER_NAME_EXISTS';END IF;IF to_regprocedure('private.pc_store_loose_items(uuid,text,integer,text)') IS NOT NULL THEN RAISE EXCEPTION 'REWARD_HELPER_NAME_EXISTS';END IF;IF to_regprocedure('private.pass_calendar_bundle(text,timestamp with time zone)') IS NOT NULL THEN RAISE EXCEPTION 'REWARD_HELPER_NAME_EXISTS';END IF;END $absent$;
CREATE TABLE private.reward_gift_boxes(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
 items jsonb NOT NULL CHECK(jsonb_typeof(items)='object'),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT statement_timestamp(),
 opened_at timestamptz,destination text CHECK(destination IN('bag','pc')),result jsonb,request_id uuid,
 pass_kind text,pass_start timestamptz,CHECK((pass_kind IS NULL)=(pass_start IS NULL)),UNIQUE(user_id,request_id),UNIQUE(user_id,pass_kind,pass_start)
);
ALTER TABLE private.reward_gift_boxes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON private.reward_gift_boxes FROM PUBLIC,anon,authenticated,service_role;
CREATE INDEX reward_gift_boxes_pending ON private.reward_gift_boxes(user_id,created_at,id) WHERE opened_at IS NULL;
